(async () => {
  const rows = await FileAttachment("sales.csv").csv({typed: true});
  const year = 2025;
  const by = d3.rollup(rows.filter(r => new Date(r.date).getUTCFullYear() === year), v => d3.sum(v, d => d.revenue), r => new Date(r.date).getUTCMonth());
  const data = d3.range(12).map(m => ({month: new Date(Date.UTC(year, m, 1)), revenue: by.get(m) ?? 0}));
  return Plot.plot({
    width: 900, height: 450, marginLeft: 70, style: {fontSize: "14px", background: "white"},
    title: `Monthly revenue, ${year}`,
    x: {type: "band", tickFormat: d => d3.utcFormat("%b")(d), label: null},
    y: {grid: true, label: "Revenue ($)", tickFormat: "s"},
    marks: [
      Plot.lineY(data, {x: "month", y: "revenue", stroke: "#2563eb", strokeWidth: 2.5}),
      Plot.dot(data, {x: "month", y: "revenue", fill: "#2563eb", r: 5, tip: true}),
      Plot.ruleY([0])
    ]
  });
})()

{
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const w = 360, r = 150;
  const color = d3.scaleOrdinal().domain(data.map(d => d.task)).range(d3.schemeTableau10);
  const arcs = d3.pie().sort(null).value(d => d.value)(data);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.62).outerRadius(r * 0.62);
  const svg = d3.create("svg").attr("viewBox", [-w / 2, -w / 2, w, w]).attr("width", w).attr("height", w);
  svg.selectAll("path").data(arcs).join("path")
    .attr("d", arc).attr("fill", d => color(d.data.task)).attr("stroke", "white");
  svg.selectAll("text").data(arcs).join("text")
    .attr("transform", d => `translate(${label.centroid(d)})`)
    .attr("text-anchor", "middle").attr("fill", "white").attr("font-size", 13)
    .text(d => `${d.data.task} ${d.data.value}%`);
  return svg.node();
}
